local baihu = fk.CreateSkill{
  name = "baihu_emblem&",
  mode_skill = true,
}

Fk:loadTranslationTable{
  ["baihu_emblem&"] = "白虎",
  [":baihu_emblem&"] = "你可以将一张牌当【杀】或【闪】使用或打出。",

  ["#baihu_emblem&"] = "白虎：你可以将一张牌当【杀】或【闪】使用或打出",
}

baihu:addEffect("viewas", {
  pattern = "slash,jink",
  prompt = "#baihu_emblem&",
  interaction = function (self, player)
    local all_names = { "slash", "jink" }
    local names = player:getViewAsCardNames(baihu.name, all_names)
    if #names == 0 then return end
    return UI.CardNameBox { choices = names, all_choices = all_names }
  end,
  handly_pile = true,
  filter_pattern = {
    min_num = 1,
    max_num = 1,
    pattern = ".",
  },
  view_as = function(self, player, cards)
    if #cards ~= 1 or not self.interaction.data then return end
    local card = Fk:cloneCard(self.interaction.data)
    card:addSubcard(cards[1])
    card.skillName = baihu.name
    return card
  end,
  before_use = function (self, player, use)
    player.room:handleAddLoseSkills(player, "-baihu_emblem&", nil, false, true)
  end,
})

baihu:addEffect(fk.TurnEnd, {
  late_refresh = true,
  can_refresh = function (self, event, target, player, data)
    return player:hasSkill(baihu.name, true) and
      not table.find(player.room.alive_players, function (p)
        return p.role:endsWith("rebel")
      end)
  end,
  on_refresh = function (self, event, target, player, data)
    player.room:handleAddLoseSkills(player, "-"..baihu.name)
  end,
})

return baihu

local fanjian = fk.CreateSkill {
  name = "fanjian",
}

fanjian:addEffect("active", {
  anim_type = "offensive",
  prompt = "#fanjian-active",
  max_phase_use_time = 1,
  card_filter = Util.FalseFunc,
  target_filter = function(self, player, to_select, selected)
    return #selected == 0 and to_select ~= player
  end,
  target_num = 1,
  on_use = function(self, room, effect)
    local player = effect.from
    local target = effect.tos[1]
    local choice = room:askToChoice(target, {
      choices = { "log_spade", "log_heart", "log_club", "log_diamond" },
      skill_name = fanjian.name,
    })
    local card = room:askToChooseCard(target, {
      target = player,
      flag = "h",
      skill_name = fanjian.name,
    })
    room:obtainCard(target, card, true, fk.ReasonPrey, target, fanjian.name)
    if Fk:getCardById(card):getSuitString(true) ~= choice and target:isAlive() then
      room:damage {
        from = player,
        to = target,
        damage = 1,
        skillName = fanjian.name,
      }
    end
  end,
})

fanjian:addAI(Fk.Ltk.AI.newActiveStrategy {
  think = function(self, ai)
    local cards = ai.player:getCardIds("h")
    local players = ai:getEnabledTargets()
    if #cards == 0 or #players == 0 then return {}, -1000 end

    local good_cards = table.filter(cards, function(id)
      return ai:getCardValue(id, "use_value") >= 45 or ai:getCardValue(id, "keep_value") >= 45
    end)
    if (#good_cards / #cards) >= 0.8 then return {}, -1000 end

    local benefits = {}
    for _, target in ipairs(players) do
      local card_benefit, all_benefits = -1, 0
      local benefits_all = table.map(cards, function(cid)
        local card_benefit_local = ai:getBenefitOfEvents(function(logic)
          logic:obtainCard(target, cid, true, fk.ReasonGive)
        end)

local fankui = fk.CreateSkill({
  name = "fankui",
})

fankui:addEffect(fk.Damaged, {
  anim_type = "masochism",
  can_trigger = function(self, event, target, player, data)
    if not (target == player and player:hasSkill(fankui.name)) then return end
    if data.from and not data.from.dead then
      if data.from == player then
        return #player:getCardIds("e") > 0
      else
        return not data.from:isNude()
      end
    end
  end,
  on_use = function(self, event, target, player, data)
    local room = player.room
    local flag = data.from == player and "e" or "he"
    local card = room:askToChooseCard(player, {
      target = data.from,
      flag = flag,
      skill_name = fankui.name,
    })
    room:obtainCard(player, card, false, fk.ReasonPrey, player, fankui.name)
  end
})

fankui:addAI(Fk.Ltk.AI.newInvokeStrategy{
  think = function(self, ai)
    local data = ai.room.logic:getCurrentEvent().data
    local player = ai.player
    local ret, benefit = player.ai:askToChooseCards({
      cards = data.from:getCardIds("he"),
      skill_name = fankui.name,
      data = {
        toArea = Card.PlayerHand,
        target = player,
        reason = fk.ReasonPrey,
        proposer = player,
      },
    })
    return ai:getBenefitOfEvents(function(logic)
      logic:obtainCard(player, ret, false, fk.ReasonPrey, player, fankui.name)
    end) > 0
  end,
})

return fankui

